head.script:
scwin.initScreen = function() {
    //초기화 및 권한체크 
    comLib.FormLoadSetting(sFORMCAPTION, sFORMLOCATION, scwin.globalVal.sBUTTONLIST, sUSERAUTH);
    //코드 바인딩
    //	var codeOption = [
    //   		  {COMM_CODE : "MAJR_ENCD", object : [grdHR_MAJRXM, cmbSHRMAJR_ENCD]}
    //   	];
    //	comLib.setCodeObject(codeOption);
    var codeOption = [{
        COMM_CODE: "MAJR_ENCD",
        object: [cmbSHRMAJR_ENCD, grdHR_MAJRXM]
    }];
    comLib.setCodeObject(codeOption);
    dtlCommonCode_MAJR_ENCD.setCondition("filter", dtlCommonCode_MAJR_ENCD.getOption("filterCondition") + " && USEX_YSNO == '1' ");
    //공통코드 filter
    //사용자콤보 바인딩
    //초기값 세팅
    ipcSHRBGIN_DATE.setValue(dateLib.CurrentDate("yyyy") + "0101");
    ipcSHRENDX_DATE.setValue(dateLib.CurrentDate("yyyy") + "1231");
    //그룹초기화
    //검색조건 포커스
    //검색 	
};
scwin.getCommonSearch = function(rtnValue) {
    if (rtnValue == false) return;
    //변경여부 체크
    if (valLib.checkModified([dtlHR_MAJRXM]) && rtnValue != true) {
        comLib.Message("TMM006", true, "getCommonSearch");
    } else {
        //필수조회조건체크
        if (!scwin.checkSearchItem()) return;
        scwin.setSubmitArg("SEARCH00");
    }
};
scwin.setCommonInput = function() {
    //row 추가
    var row = dtlHR_MAJRXM.insertRow(); //행추가
    //초기값세팅
    //입력행 포커스
    grdHR_MAJRXM.setFocusedCell(row, "EMPL_NAME", true);
};
scwin.setCommonDelete = function(rtnValue) {
    if (rtnValue == false) return;
    if (dtlHR_MAJRXM.getTotalRow() > 0) {
        if (rtnValue == true) {
            comLib.removeGridView(grdHR_MAJRXM);
        } else {
            //삭제여부 확인
            scwin.checkDelete();
        }
    } else {
        comLib.Message("TMM007", true); //삭제 자료 없음 정보 Display
    }
};
scwin.setCommonSave = function() {
    if (!scwin.checkSaveItem()) return;
    scwin.setSubmitArg("SAVE00");
};
scwin.getCommonPrint = function() {
    //기능없음.
};
scwin.setSubmitArg = function(sMethodName, sKind) {
    var option;
    switch (sMethodName) {
        case 'SEARCH00':
            option = {
                id: sMethodName,
                action: "/HRMB0160/SEARCH00.do",
                ref: "data:json, {'id':'dtmSEARCH00', 'key':'param'}",
                target: "data:json, {'id':'dtlHR_MAJRXM', 'key':'data'}",
                submitDoneHandler: "setPostProcess"
            };
            break;
        case 'SAVE00':
            option = {
                id: sMethodName,
                action: "/HRMB0160/SAVE00.do",
                ref: "data:json,{'id':'dtlHR_MAJRXM', 'action':'modified', 'key':'HR_MAJRXM'}",
                submitDoneHandler: "setPostProcess",
                isShowMeg: true
            };
            break;
        default:
            break;
    }
    ajaxLib.executeSubmission(option);
};
scwin.setPostProcess = function(sMethodName, e) {
    if (ajaxLib.IsWarning(e)) {
        return;
    }
    switch (sMethodName) {
        case 'SEARCH00':
            //조회 후 첫번째 행 선택
            grdHR_MAJRXM.setFocusedCell(0, 0);
            //상태값에 조회건수 표시
            comLib.Information(optInformation, e, "S");
            break;
        case 'SAVE00':
            if (comLib.Result(e) > 0) {
                dtlHR_MAJRXM.reform();
                scwin.changeRowIndex(grdHR_MAJRXM.getFocusedRowIndex(), -1);
                comLib.Information(optInformation, e, "C");
                scwin.getCommonSearch();
            }
            break;
        default:
            break;
    }
};
scwin.openHelpDialog = function(obj, sFromGrd, colID) {
    resultTest = true;
    //alert("들어옴");
    if (!comLib.bUsePopup) return;
    if (typeof obj == "object" || typeof obj == "undefined") {
        obj = this;
    };
    var param = new Array();
    var arrParam = new Array();
    if (obj.id == "imgHelpSHRDEPT_CODE" || obj.id == "iptSHRDEPT_NAME") {
        if (iptSHRDEPT_NAME.getReadOnly()) return;
        //부서코드(조회조건)
        param[0] = new Array("DEPT_NAME", iptSHRDEPT_NAME.getValue());
        param[1] = new Array("USEX_YSNO", "0"); //1:사용부서, 0:전체부서
        arrParam[0] = "TMM0004"; //Popup ID
        arrParam[1] = param; //parameter
        arrParam[2] = "iptSHRDEPT_CODE,iptSHRDEPT_NAME,cmbSHRWORK_PLAC"; //초기화 및 결과 Mapping Column
        arrParam[3] = "DEPT_CODE,DEPT_NAME,WORK_PLAC"; //Mapping Column
        comLib.HelpDialog(obj, arrParam);
    } else if (obj.id == "imgHelpSHREMPL_NUMB" || obj.id == "iptSHREMPL_NAME") {
        if (iptSHREMPL_NAME.getReadOnly()) return;
        //사원번호(조회조건)
