        param[1] = new Array("ENFC_CODE", cmbSHRMAJR_ENCD.getValue());
        param[2] = new Array("JBGP_CODE", "DB3");
        param[3] = new Array("USEX_YSNO", "0"); //0:전체, 1:재직자
        arrParam[0] = "HRM0027"; //Popup ID				
        arrParam[1] = param; //parameter					
        arrParam[2] = "iptSHREMPL_NUMB,iptSHREMPL_NAME"; //초기화 및 결과 Mapping Column
        arrParam[3] = "EMPL_NUMB,EMPL_NAME"; //Mapping Column
        comLib.HelpDialog(obj, arrParam);
    } else if (eval(obj).id == "grdHR_MAJRXM") {
        if (colID == "EMPL_NAME") {
            alert(1);
            var nRow = grdHR_MAJRXM.getFocusedRowIndex();
            param[0] = new Array("EMPL_NAME", dtlHR_MAJRXM.getCellData(nRow, "EMPL_NAME"));
            param[1] = new Array("JBGP_CODE", "DB3");
            param[2] = new Array("USEX_YSNO", "1"); //0:전체, 1:재직자
            arrParam[0] = "HRM0027"; //Popup ID				
            arrParam[1] = param; //parameter					
            arrParam[2] = "EMPL_NUMB,EMPL_NAME"; //초기화 및 결과 Mapping Column
            arrParam[3] = "EMPL_NUMB,EMPL_NAME"; //Mapping Column
            arrParam[4] = sFromGrd;
