scwin.changeRowIndex = function(row, oldRow) {
    //KEY 필드 DISABLE
    if (dtlHR_MAJRXM.getRowStatus(row) == "C") {
        grdHR_MAJRXM.setCellReadOnly(row, "EMPL_NAME", false);
        grdHR_MAJRXM.setCellReadOnly(row, "BGIN_DATE", false);
        grdHR_MAJRXM.setCellReadOnly(row, "ENDX_DATE", false);
        grdHR_MAJRXM.setCellReadOnly(row, "MAJR_ENCD", false);
    } else {
        grdHR_MAJRXM.setCellReadOnly(row, "EMPL_NAME", true);
        grdHR_MAJRXM.setCellReadOnly(row, "BGIN_DATE", true);
        grdHR_MAJRXM.setCellReadOnly(row, "ENDX_DATE", true);
        grdHR_MAJRXM.setCellReadOnly(row, "MAJR_ENCD", true);
    }
};
scwin.changeGridView = function(info) {
    scwin.openHelpDialog("grdHR_MAJRXM", true, grdHR_MAJRXM.getColumnID(info.colIndex));
};
scwin.changeDatalist = function(info) {
    //기능없음	 
};
scwin.checkFormUnload = function() {
    comLib.CheckFormUnload([dtlHR_MAJRXM]);
};
scwin.checkSearchItem = function() {
    return valLib.validateGroup(grpSearchArea);
};
scwin.checkDelete = function() {
    var iSelectRowCount = grdHR_MAJRXM.getAllFocusedRowIndex().length;
    if (iSelectRowCount == 0) {
        //삭제할 자료를 선택해 주세요.
        comLib.Message("TMM020", true);
        return false;
    } else if (iSelectRowCount == 1) {
        // 한 건 삭제 처리시 해당 항목에 대한 삭제 여부 확인	
        var row = grdHR_MAJRXM.getFocusedRowIndex();
        var sQuestionText = "사원명 : " + dtlHR_MAJRXM.getCellData(row, "EMPL_NAME");
        comLib.Message("TMM002", true, sQuestionText, "setCommonDelete");
    } else if (iSelectRowCount > 1) {
        comLib.Message("TMM004", true, iSelectRowCount, "setCommonDelete");
    }
};
scwin.checkSaveItem = function() {
    //변경된 자료가 있는지 체크
    if (valLib.checkModified([dtlHR_MAJRXM], true)) {
        //필수 입력 항목 체크
        var valInfo = [{
                id: "EMPL_NAME",
                mandatory: true
            }, //사원명
            {
                id: "BGIN_DATE",
                mandatory: true,
                isStart: true
            }, //시작일
            {
                id: "ENDX_DATE",
                mandatory: true,
                isEnd: true
            }, //종료일
            {
                id: "MAJR_ENCD",
                mandatory: true
            }
        ]; //사업장
        return valLib.validateGridView(grdHR_MAJRXM, valInfo);
    } else {
        return false;
    }
};
scwin.btnFormDown_onClick = function(e) {
    comLib.DownloadExcelSample("HRMB0160");
};
scwin.excelUpload = function(e) {
    /**
     * 엑셀 업로드 속성 정의
     * options.type <String:N> [defalut:	0] 1이면 엑셀 파일이 그리드의 보이는 결과로 만들어져있을때  0이면 엑셀 파일이 그리드의 실제 데이터로 구성되어있을때 
     * options.sheetNo <Number:N> [defalut:	0] excel파일에서 그리드의 데이터가 있는 sheet번호 
     * options.startRowIndex <Number:N> [defalut:	0] excel파일에서 그리드의 데이터가 시작되는 행의 번호(헤더 포함) 
     * options.startColumnIndex <Number:N> [defalut:	0] excel파일에서 그리드의 데이터가 시작되는 열의 번호 
     * options.endColumnIndex <Number:N> [defalut: 0] excel파일에서 그리드의 데이터가 끝나는 열의 index ( 엑셀컬럼수가 그리드컬럼수 보다 작은 경우 그리드 컬러수를 설정) 
     * options.headerExist <String:N> [defalut:	0] excel파일에서 그리드의 데이터에 header가 있는지 여부(1이면 header 존재 0이면 없음) 
     * options.footerExist <String:N> [defalut: 1] excel파일에서 그리드의 데이터에 footer가 있는지 여부(1이면 footer 존재 0이면 없음 기본값은 1 그리드에 footer가 없으면 적용되지 않음) 
     * options.append <String:N> [defalut: 0] excel파일에서 가져온 데이터를 그리드에 append시킬지 여부(1이면 현재 그리드에 데이터를 추가로 넣어줌 0이면 현재 그리드의 데이터를 삭제하고 넣음) 
     * options.hidden <String:N> [defalut: 0] 읽어들이려는 엑셀파일에 hidden column이 저장되어 있는지 여부를 설정하는 int형 숫자(0이면  엑셀파일에 hidden 데이터가 없으므로 그리드 hidden column에 빈 데이터를 삽입  1 : 엑셀파일에 hidden 데이터가 있으므로 엑셀 파일로부터 hidden 데이터를 삽입 ) 
     * options.fillHidden <String:N> [defalut: 0] Grid에 hiddenColumn에 빈 값을 넣을지를 결정하기 위한 int형 숫자(1이면 hidden Column에 빈 값을 저장하지 않음,0이면 hidden column이 저장되어있지 않은 Excel File이라 간주하고 hidden Column에 빈 값을 넣어줌)(hidden이 0인 경우에는 fillhidden은 영향을 끼치지 않음) 
     * options.skipSpace <String:N> [defalut: 0] 공백무시 여부(1이면 무시 0이면 포함) 
     * options.insertColumns <Array:N> radio, checkbox와 같은 컬럼을 엑셀에서 받아 오지 않고, 사용자 컬럼 설정 으로 업로드 ( 데이터 구조 : [ { columnIndex:1, columnValue:"1" } ] ) 
     * options.popupUrl <String:N> 업로드시에 호출할 popup의 url 
     */
    scwin.globalVal.upBtn = this.id;
    var options = {
        type: "0", // 1 : GridView의 컬럼만 포함한 경우, 0 : GridView의 실제 DataCollection으로 구성된 경우일까??
        sheetNo: 0,
        headerExist: "1",
        startRowIndex: 0,
        startColumnIndex: 0,
        append: "0",
        hidden: "1",
        fillHidden: "1",
        insertColumns: [{
            columnIndex: 0,
            columnValue: "0"
        }]
    };
    comLib.uploadExcel(grdHR_MAJRXM, options);
};
scwin.postExcelUpload = function(value) {
    if (scwin.globalVal.upBtn == "btnFormUp") {
        dtlHR_MAJRXM.modifyAllStatus("C");
    } else if (scwin.globalVal.upBtn == "btnFormUp2") {
        dtlHR_MAJRXM.modifyAllStatus("U");
    }
};
scwin.cmbSHRDEPT_CODE_onviewchange = function(info) {
    if (cmbSHRWORK_PLAC.getValue() == "") {
        iptSHRDEPT_NAME.setValue("");
        iptSHRDEPT_CODE.setValue("");
        iptSHRDEPT_NAME.setReadOnly(true);
    } else {
        iptSHRDEPT_NAME.setReadOnly(false);
    }
};
scwin.dbClick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.clickImage = function() {
    var im = document.getElementsByTagName("img");
    im[0].click()
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 브라우저에서 imageClickFunction 이 적용된 근무지 1, 2, 3 등의 1차 평가자의 우측, 2차 평가자의 우측 등의 컬럼을 더블클릭한다.
    //1. Double-click on the right side of the primary evaluator, the right side of the secondary evaluator, etc., at work 1, 2, 3, etc., where imageClickFunction is applied in the browser.
    WebSquare.wUnit.addCommand("set", "scwin.dbClick($p.id+'grdHR_MAJRXM_cell_0_10')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.dbClick($p.id+'grdHR_MAJRXM_cell_0_13')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.dbClick($p.id+'grdHR_MAJRXM_cell_0_15')");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify step 1. 버튼이 나오게 된다.
    //1. The button appears.
    WebSquare.wUnit.addCommand("assert", "document.getElementsByTagName('img').length == 2", "true");
    //Test step 2. 버튼을 클릭한다. 
    //2. Click the button.
    WebSquare.wUnit.addCommand("set", "scwin.clickImage()");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify step 2. imageClickFunction 이 동작해서 '들어옴' 팝업이 생성된다. (20170320 엔진에서는 imageClickFunction 이 동작하지 않아서 팝업이 생성되지 않음)
    //2. The imageClickFunction works to create a 'pop-up' pop-up. (ImageClickFunction does not work on the 20170320 engine, so no pop-ups are generated)
    WebSquare.wUnit.addCommand("assert", "resultTest", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
